import React, { useEffect, useState } from 'react';
import { db } from '../firebase-config';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { auth } from '../firebase-config';

const Profile = () => {
  const [activities, setActivities] = useState([]);
  const [totalRemainingSadaqa, setTotalRemainingSadaqa] = useState(0);

  useEffect(() => {
    const fetchActivities = async () => {
      try {
        const user = auth.currentUser;
        if (user) {
          const activitiesCollectionRef = collection(db, 'activities');
          const q = query(activitiesCollectionRef, where('userId', '==', user.uid));
          const querySnapshot = await getDocs(q);

          const fetchedActivities = [];
          let sadaqaRemaining = 0;

          querySnapshot.forEach((doc) => {
            const data = doc.data();
            fetchedActivities.push({ id: doc.id, ...data });

            // Calculer le montant restant pour les Sadaqa
            if (data.sadaqaStatus === 'Pas encore' || data.sadaqaStatus === 'Partiellement payé') {
              const remaining = data.sadaqaAmount - (data.sadaqaPaid || 0);
              sadaqaRemaining += remaining;
            }
          });

          setActivities(fetchedActivities);
          setTotalRemainingSadaqa(sadaqaRemaining);
        }
      } catch (error) {
        console.error('Erreur lors du chargement des activités :', error);
      }
    };

    fetchActivities();
  }, []);

  return (
    <div className="container mt-5">
      <h1 className="text-center mb-4">👤 Profil</h1>

      {/* Afficher les activités par jour */}
      <div className="card">
        <div className="card-body">
          <h3 className="card-title">📅 Activités par jour</h3>
          {activities.map((activity) => (
            <div key={activity.id} className="mb-3">
              <h5>{new Date(activity.date).toLocaleDateString()}</h5>
              <p>Investissement : {activity.investment} Dhs</p>
              <p>Gains totaux : {activity.totalGains} Dhs</p>
              <p>Sadaqa : {activity.sadaqaAmount} Dhs</p>
              <p>Statut de la Sadaqa : {activity.sadaqaStatus}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Afficher le montant total restant pour les Sadaqa */}
      <div className="card mt-4">
        <div className="card-body">
          <h3 className="card-title">🤲 Sadaqa restante</h3>
          <p>Montant total restant : <strong>{totalRemainingSadaqa.toFixed(2)} Dhs</strong></p>
        </div>
      </div>
    </div>
  );
};

export default Profile;
